INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q208261', 'Ionian Revolt', 'The Ionian Revolt, and associated revolts in Aeolis, Doris, Cyprus and Caria, were military rebellions by several Greek regions of Asia Minor against Persian rule, lasting from 499 BC to 493 BC. At the heart of the rebellion was the dissatisfaction of the Greek cities of Asia Minor with the tyrants appointed by Persia to rule them, along with the individual actions of two Milesian tyrants, Histiaeus and Aristagoras. The cities of Ionia had been conquered by Persia around 540 BC, and thereafter were ruled by native tyrants, nominated by the Persian satrap in Sardis.', -499, NULL, NULL, -493, NULL, NULL, 'year', '499 BCE – 493 BCE', 71, 'https://en.wikipedia.org/wiki/Ionian_Revolt'),
  ('Q1247317', 'Battle of Salamis', 'The Battle of Salamis in 306 BC took place off Salamis, Cyprus between the fleets of Ptolemy I of Egypt and Antigonus I Monophthalmus, two of the Diadochi, the generals who, after the death of Alexander the Great, fought each other for control of his empire. Cyprus had been seized by Ptolemy, and was used as a base for operations against the Antigonid territories in Asia Minor and the Levant.', -306, NULL, NULL, NULL, NULL, NULL, 'year', '306 BCE', 58, 'https://en.wikipedia.org/wiki/Battle_of_Salamis_(306_BC)'),
  ('Q1086625', 'Siege of Famagusta', 'The siege of Famagusta happened in Venetian-controlled Famagusta, the last Christian possession in Cyprus. Famagusta was captured by the Ottomans in August 1571 after a siege that lasted nearly a year.', 1570, 9, 17, 1571, 8, 5, 'day', '17 September 1570 – 5 August 1571', 58, 'https://en.wikipedia.org/wiki/Siege_of_Famagusta'),
  ('Q3555069', 'Cyprus Convention', 'The Cyprus Convention of 4 June 1878 was a secret agreement reached between the United Kingdom and the Ottoman Empire which granted administrative control of Cyprus to Britain (see British Cyprus), in exchange for its support of the Ottomans during the Congress of Berlin. Provisions in the Convention retained Ottoman rights over the territory of Cyprus.', 1878, 6, 4, NULL, NULL, NULL, 'day', '4 June 1878', 57, 'https://en.wikipedia.org/wiki/Cyprus_Convention'),
  ('Q5911717', '1953 Paphos earthquake', 'The 1953 Paphos earthquake struck off the coast of Paphos on Cyprus at 07:05 EEST on 10 September. The earthquake with a magnitude of Mw 6.3 or Ms 6.5, occurred at a depth of 20 km (12 mi).', 1953, 9, 10, NULL, NULL, NULL, 'day', '10 September 1953', 34, 'https://en.wikipedia.org/wiki/1953_Paphos_earthquake'),
  ('Q245831', 'Cyprus problem', 'There is an ongoing dispute between the Greek and Turkish communities in Cyprus over how the island should be governed. A key issue is the conflicting wishes of some Greek Cypriots for union with Greece (Enosis) and of some Turkish Cypriots for the island to be partitioned between the communities (Taksim).', 1955, 4, 1, 1974, 8, 18, 'day', '1 April 1955 – 18 August 1974', 65, 'https://en.wikipedia.org/wiki/Cyprus_problem'),
  ('Q3434446', 'Battle of Tylliria', 'The Battle of Tillyria (Greek: Μάχη της Τηλλυρίας) or Battle of Kokkina (Greek: Μάχη των Κοκκίνων), known in Turkish as Erenköy Resistance (Turkish: Erenköy Direnişi), was a conflict on 6 August 1964 between units of the Cypriot National Guard and Turkish Cypriot armed groups in Kokkina area of Cyprus.', 1964, 8, NULL, NULL, NULL, NULL, 'month', 'August 1964', 41, 'https://en.wikipedia.org/wiki/Battle_of_Tillyria'),
  ('Q3556320', 'Ecclesiastical coup', 'The Ecclesiastical coup is the name given to the events staged by three bishops of the Orthodox Church of Cyprus against the President of the Republic of Cyprus, Archbishop Makarios III, in the period from March 1972 to July 1973.', 1973, 7, 14, 1973, 7, 14, 'day', '14 July 1973', 34, 'https://en.wikipedia.org/wiki/1972%E2%80%931973_Cypriot_ecclesiastical_coup_attempt'),
  ('Q1050999', 'Turkish invasion of Cyprus', 'Turkey invaded Cyprus on 20 July 1974 in an operation that progressed in two phases over the following month. Taking place upon a background of intercommunal violence between Greek and Turkish Cypriots, and in response to a Greek junta-sponsored Cypriot coup d''état five days earlier, it led to the Turkish capture and occupation of the northern part of the island.', 1974, 8, 18, 1974, 8, 18, 'day', '18 August 1974', 74, 'https://en.wikipedia.org/wiki/Turkish_invasion_of_Cyprus'),
  ('Q1862197', 'Maratha, Santalaris and Aloda massacre', 'Maratha, Santalaris and Aloda massacre (Turkish: Muratağa, Sandallar ve Atlılar katliamı) refers to a massacre of Turkish Cypriots by EOKA-B; a Greek Cypriot paramilitary group that took place on 14 August 1974 in the villages of Maratha, Santalaris and Aloda. In the massacre, a total of 126 unarmed innocent Turkish Cypriots were killed, with the youngest being 16 days old and the oldest 95 years old.', 1974, 8, 14, NULL, NULL, NULL, 'day', '14 August 1974', 56, 'https://en.wikipedia.org/wiki/Maratha%2C_Santalaris_and_Aloda_massacre'),
  ('Q2069434', '1974 Cypriot coup d''état', 'A military coup d''état was executed by the Cypriot National Guard on 15 July 1974 with Greek support. The coup plotters removed the sitting President of Cyprus, Archbishop Makarios III, from office and installed pro-Enosis nationalist Nikos Sampson.', 1974, 7, 15, NULL, NULL, NULL, 'day', '15 July 1974', 57, 'https://en.wikipedia.org/wiki/1974_Cypriot_coup_d''%C3%A9tat'),
  ('Q4872013', 'Battle of Pentemili beachhead', 'Pentemili is the Cypriot beach where troops first landed on the morning of 20 July 1974 in the Turkish invasion of Cyprus. It is located 5 miles (8 km) west of Kyrenia, thus the name.', 1974, 7, 20, 1974, 7, 22, 'day', '20 July 1974 – 22 July 1974', 34, 'https://en.wikipedia.org/wiki/Battle_of_Pentemili_beachhead'),
  ('Q6044625', 'Tochni massacre', 'The Tochni massacre refers to the killing of 84 Turkish Cypriots from the village of Tochni, Larnaca, Cyprus by Greek Cypriot members of EOKA B during the Turkish invasion of Cyprus in the summer of 1974.', 1974, 8, 14, NULL, NULL, NULL, 'day', '14 August 1974', 39, 'https://en.wikipedia.org/wiki/Tochni_massacre'),
  ('Q12061791', 'military operations during the Turkish invasion of Cyprus', 'In 1974, Turkey invaded the northern portion of the Republic of Cyprus in response to a military coup taking place on the island, in attempt to annex the island to Greece. Turkey claimed that this was an intervention in accordance to Treaty of Guarantee.', 1974, 8, 18, 1974, 8, 18, 'day', '18 August 1974', 34, 'https://en.wikipedia.org/wiki/Military_operations_during_the_Turkish_invasion_of_Cyprus'),
  ('Q15991234', 'Treaty Establishing the European Stability Mechanism', 'The Treaty Establishing the European Stability Mechanism was signed by the member states of the eurozone to found the European Stability Mechanism (ESM), an international organisation located in Luxembourg, to act as a permanent source of financial assistance for member states in financial difficulty, with a maximum lending capacity of €500 billion. It replaced two earlier temporary EU funding programmes: the European Financial Stability Facility (EFSF) and the European Financial Stabilisation Mechanism (EFSM).', 2012, 2, 2, NULL, NULL, NULL, 'day', '2 February 2012', 34, 'https://en.wikipedia.org/wiki/Treaty_establishing_the_European_Stability_Mechanism'),
  ('Q55389162', '2018 Cyprus gas dispute', 'The 2018 Cyprus gas dispute is a diplomatic dispute involving the exclusive economic zone (EEZ) of the Republic of Cyprus (in partnership with Greece and Egypt) in the eastern Mediterranean, which began on February 6, 2018. The dispute followed remarks made by Turkey''s foreign minister Mevlüt Çavuşoğlu, rejecting a 2003 Cypriot-Egyptian maritime border demarcation deal and announcing the Turkish government''s intention to carry out gas exploration in the region.', 2018, 2, 6, NULL, NULL, NULL, 'day', '6 February 2018', 37, 'https://en.wikipedia.org/wiki/2018_Cyprus_gas_dispute'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q86458103', 'COVID-19 pandemic in Europe', 'The global COVID-19 pandemic arrived in Europe with its first confirmed case in Bordeaux, France, on 24 January 2020, and subsequently spread widely across the continent. By 17 March 2020, every country in Europe had confirmed a case, and all have reported at least one death, with the exception of Vatican City.', 2020, 1, 24, NULL, NULL, NULL, 'day', '24 January 2020', 65, 'https://en.wikipedia.org/wiki/COVID-19_pandemic_in_Europe');
